tools.example:
fc = 3e9; c = physconst('LightSpeed'); lambda = c/fc;
ula = phased.ULA(NumElements=8, ElementSpacing=lambda/2);
pattern(ula, fc, -90:90, 0, CoordinateSystem='rectangular', Type='powerdb')
pos = getElementPosition(ula);

ura = phased.URA(Size=[4 8], ElementSpacing=[0.05 0.05]);
viewArray(ura, ShowIndex='All')
pattern(ura, 3e9, -180:180, -90:90, Type='powerdb')

uca = phased.UCA(NumElements=12, Radius=0.3);
viewArray(uca)
sv = phased.SteeringVector(SensorArray=uca);
w = sv(1e9, [45; 0]);

N = 16; th = linspace(0, 360, N+1); th(end) = [];
pos = 0.2*[cosd(th); sind(th); zeros(1,N)];
nv = [th; zeros(1,N)];
arr = phased.ConformalArray(ElementPosition=pos, ElementNormal=nv);
viewArray(arr, ShowNormals=true)

el = phased.CosineAntennaElement(CosinePower=[2 2]);
ula = phased.ULA(NumElements=8, ElementSpacing=0.05, Element=el);
pattern(ula, 3e9, -90:90, 0, Type='directivity')

ula = phased.ULA(NumElements=8, ElementSpacing=0.05);
sv = phased.SteeringVector(SensorArray=ula);
w = sv(3e9, [30; 0]);       % 8-by-1 steering vector toward az 30 deg
w2 = sv(3e9, [-20 0 40; 0 0 0]);   % three directions

ula = phased.ULA(8, 0.05);
resp = phased.ArrayResponse(SensorArray=ula, WeightsInputPort=true);
sv = phased.SteeringVector(SensorArray=ula);
w = sv(3e9, [20; 0]);
ang = -90:90;
p = resp(3e9, [ang; zeros(size(ang))], w);
plot(ang, mag2db(abs(p)))

ula = phased.ULA(16, 0.05);
gain = phased.ArrayGain(SensorArray=ula);
g = gain(3e9, [0; 0])   % about 10*log10(16) = 12 dB

pos = (0:7)*0.5;           % half-wavelength ULA
sv = steervec(pos, [30 -10]);   % 8-by-2
w = cbfweights(pos, 30);

pos = (0:9)*0.5;
w = cbfweights(pos, 20);
ang = -90:90;
sv = steervec(pos, ang);
plot(ang, mag2db(abs(w'*sv)))

pos = (0:9)*0.5;
ncov = 0.1; scov = [1 0; 0 3];
cov = sensorcov(pos, [30 -20], ncov, scov);
w = mvdrweights(pos, 30, cov);
plot(-90:90, mag2db(abs(w'*steervec(pos, -90:90))))

pos = (0:9)*0.5;
cov = sensorcov(pos, [30 -20], 0.01, [1 0; 0 10]);
constr = steervec(pos, [30 -20]);   % unit gain at 30, null at -20
w = lcmvweights(constr, [1; 0], cov);

ula = phased.ULA(8, 0.05);
x = collectPlaneWave(ula, randn(200, 1), [20; 0], 3e9) + 0.1*randn(200, 8);
bf = phased.PhaseShiftBeamformer(SensorArray=ula, OperatingFrequency=3e9, Direction=[20; 0], WeightsOutputPort=true);
[y, w] = bf(x);

ula = phased.ULA(10, 0.05); fc = 3e9;
t = (0:999)'/1e4;
x = collectPlaneWave(ula, [sin(2*pi*50*t) 5*randn(1000,1)], [30 -40; 0 0], fc) + 0.1*randn(1000, 10);
bf = phased.MVDRBeamformer(SensorArray=ula, OperatingFrequency=fc, Direction=[30; 0], DiagonalLoadingFactor=1e-3, WeightsOutputPort=true);
[y, w] = bf(x);

ula = phased.ULA(10, 0.05); fc = 3e9;
sv = phased.SteeringVector(SensorArray=ula);
C = sv(fc, [30 -40; 0 0]);
bf = phased.LCMVBeamformer(Constraint=C, DesiredResponse=[1; 0]);
y = bf(x);

mic = phased.OmnidirectionalMicrophoneElement(FrequencyRange=[20 20e3]);
ula = phased.ULA(8, 0.04, Element=mic);
bf = phased.TimeDelayBeamformer(SensorArray=ula, PropagationSpeed=343, SampleRate=16e3, Direction=[30; 0]);
y = bf(x);

ula = phased.ULA(10, 0.05); fc = 3e9;
x = collectPlaneWave(ula, randn(500, 2), [20 -35; 0 0], fc) + 0.1*randn(500, 10);
est = phased.BeamscanEstimator(SensorArray=ula, OperatingFrequency=fc, DOAOutputPort=true, NumSignals=2);
[~, doa] = est(x)
plotSpectrum(est)

wav = phased.LinearFMWaveform(SampleRate=1e6, PulseWidth=20e-6, PRF=5e3, SweepBandwidth=500e3);
x = wav();
plot(wav)
mf = phased.MatchedFilter(Coefficients=getMatchedFilter(wav));
y = mf(x);

fs = 150e6; bw = 150e6; tm = 5.5*range2time(200, physconst('LightSpeed'));
wav = phased.FMCWWaveform(SampleRate=fs, SweepTime=tm, SweepBandwidth=bw, SweepDirection='Triangle');
x = wav();
slope = bw/tm;
% ... after propagation: y = dechirp(rx, x); r = beat2range(fb, slope)

wav = phased.PhaseCodedWaveform(Code='Barker', NumChips=13, ChipWidth=1e-6, SampleRate=10e6, PRF=1e3);
x = wav();
[afmag, delay] = ambgfun(x, wav.SampleRate, wav.PRF, 'Cut', 'Doppler');
plot(delay, mag2db(afmag))

tx = phased.Transmitter(PeakPower=1e3, Gain=20, InUseOutputPort=true);
[xt, status] = tx(x);
% ... radiator, channel, target, collector, receiver:
rx = phased.ReceiverPreamp(Gain=20, NoiseFigure=3, SampleRate=1e6, EnableInputPort=true);
y = rx(rxsig, ~status);

ula = phased.ULA(4, 0.05);
rad = phased.Radiator(Sensor=ula, OperatingFrequency=3e9, WeightsInputPort=true);
sv = phased.SteeringVector(SensorArray=ula);
w = sv(3e9, [10; 0]);
y = rad(xt, [10; 0], w);   % toward the target at 10 deg azimuth

tgtplat = phased.Platform(InitialPosition=[2000; 500; 0], Velocity=[-40; 0; 0]);
for k = 1:10
    [tpos, tvel] = tgtplat(1/prf);
    [rng, ang] = rangeangle(tpos, [0;0;0]);
end

wav = phased.LinearFMWaveform(SampleRate=1e6, PulseWidth=20e-6, PRF=5e3, SweepBandwidth=500e3);
mf = phased.MatchedFilter(Coefficients=getMatchedFilter(wav), SpectrumWindow='Hamming', GainOutputPort=true);
[y, g] = mf(rx);
plot(abs(y))

c = physconst('LightSpeed'); lambda = c/3e9;
rng_gates = (0:numel(y)-1)*c/(2*fs);
tvg = phased.TimeVaryingGain(RangeLoss=2*fspl(rng_gates, lambda), ReferenceLoss=2*fspl(5000, lambda));
y2 = tvg(y);

cfar = phased.CFARDetector(NumTrainingCells=40, NumGuardCells=4, ProbabilityFalseAlarm=1e-6, ThresholdOutputPort=true);
x = abs(y).^2;             % square-law input
cut = 25:numel(x)-24;
[det, th] = cfar(x, cut);
plot(cut, 10*log10([x(cut) th]))

cfar2 = phased.CFARDetector2D(GuardBandSize=[2 2], TrainingBandSize=[6 6], ProbabilityFalseAlarm=1e-5, OutputFormat='Detection index');
[r, d] = meshgrid(9:size(rdm,1)-8, 9:size(rdm,2)-8);
cut = [r(:) d(:)]';
dets = cfar2(abs(rdm).^2, cut);

rdr = phased.RangeDopplerResponse(SampleRate=fs, PropagationSpeed=c, OperatingFrequency=fc, DopplerOutput='Speed', PRFSource='Property', PRF=prf);
[resp, rgrid, sgrid] = rdr(datacube, getMatchedFilter(wav));
imagesc(sgrid, rgrid, mag2db(abs(resp))); axis xy; xlabel('Speed (m/s)'); ylabel('Range (m)')

rar = phased.RangeAngleResponse(SensorArray=ula, SampleRate=fs, OperatingFrequency=fc, RangeMethod='Matched filter');
[resp, rgrid, agrid] = rar(x, getMatchedFilter(wav));
imagesc(agrid, rgrid, mag2db(abs(resp))); axis xy

lambda = physconst('LightSpeed')/10e9;
snr = radareqsnr(lambda, 20e3, 1e3, 1e-6, RCS=1, Gain=30, Loss=3)   % dB
rmax = radareqrng(lambda, 13, 1e3, 1e-6, RCS=1, Gain=30, Loss=3)     % range for 13 dB SNR

pfa = 1e-6;
th = npwgnthresh(pfa, 10, 'noncoherent');   % dB
noisepow = rx.NoiseFigure;  % or measured
threshold = noisepow*db2pow(th);

c = physconst('LightSpeed');
k = physconst('Boltzmann');
lambda = c/2.4e9;
noisePower = k*290*1e6;   % kTB for 1 MHz

y = dechirp(rx, x);
Y = fft(y);
fb = (0:numel(y)-1)*fs/numel(y);
[~, idx] = max(abs(Y(1:end/2)));
r = beat2range(fb(idx), bw/tm, physconst('LightSpeed'))

sc = radarScenario(UpdateRate=1, StopTime=10);
rdr = radarDataGenerator(1, 'No scanning', FieldOfView=[90 10], UpdateRate=1);
platform(sc, Position=[0 0 0], Sensors=rdr);
tgt = platform(sc, Trajectory=kinematicTrajectory(Position=[5000 0 0], Velocity=[-100 0 0]));
while advance(sc)
    dets = detect(sc);
    fprintf('%d detections at t=%.1f\n', numel(dets), sc.SimulationTime);
end

radar = radarTransceiver(Waveform=phased.LinearFMWaveform(SampleRate=1e6, PRF=1e3, SweepBandwidth=500e3), NumRepetitions=32);
radar.ReceiveAntenna.Sensor = phased.ULA(8, 0.05);
tgt = struct('Position', [3000 0 0], 'Velocity', [-30 0 0]);
iq = radar(tgt, 0);     % samples x elements x pulses
